/* This file is generated by scripts/login-art/make-card.mjs; do not edit manually.
 * To change visuals, modify src/start/BrandGlow.tsx (the on-screen version) and rerun the generation
 * script so both sides render the exact same GLSL. Generation time is not written into the file to
 * avoid needless diffs on every rerun.
 *
 * This card exists for only one purpose: letting PromptCut's own renderer **prerender it into a
 * looping video** (user decision, 2026-10-24). Visuals are written as a function of frame clock t,
 * without running an internal frame loop, conforming to server/card-authoring-guide.md.
 * uLoop = fractional part of (t / loopSeconds); a full cycle returns byte-for-byte to the start,
 * so the first and last frames connect seamlessly.
 */
import { useLayoutEffect, useRef } from "react";
import type { CardDef, CardProps } from "../../kernel/types";

interface Params {
  /** Base color (--bg on official site, --ui-bg in this repository's "Flow" skin) */
  bg: string;
  /** Color of the first light orb (on-screen version takes --ui-accent; hardcoded here, export must be replayable) */
  colA: string;
  /** Color of the second light orb */
  colB: string;
  /** Seconds per loop cycle */
  loopSeconds: number;
}

const WIDTH = 559;
const HEIGHT = 1290;

const LOOK = {
  /**
   * Seconds per drift cycle. This option has no effect when `drift` is 0.
   *
   * This value is also the **length of the prerendered looping video**: phases of both light orbs
   * are integer harmonic multiples of uLoop; uLoop going from 0 to 1 returns exactly to the start,
   * so the first and last frames compute identically and the loop connects seamlessly.
   * 28 seconds × 24 frames = 672 frames, an exact integer, never off by half a frame.
   */
  loopSeconds: 28,
  /** How far each light orb drifts (CSS pixels). 0 = completely static, avoiding frame-by-frame redraws */
  drift: 110,

  /**
   * Reference viewport (CSS pixels): the two position sets below were tuned at **this size**.
   *
   * (user decision, 2026-10-23): "Align with the center of the fill-screen version." So the two light
   * orbs are not placed by current viewport ratio, which would make mobile and widescreen compositions
   * completely different, but converted to **fixed pixel offsets relative to screen center**:
   *
   *     center = viewport center + (position - 0.5) × reference viewport
   *
   * When the viewport is exactly the reference size, this formula reduces to "position × reference
   * viewport", identical to what was seen on the tuning console; smaller screens get a center crop of
   * the same composition, while larger screens expose an extra margin. The radius is inherently fixed
   * pixels and does not scale.
   *
   * 559×1290 was the actual size of the "fill widescreen" preview on the tuning console at the time.
   */
  refW: 559,
  refH: 1290,

  /** First orb (cool color, pressing in from top-left) */
  ax: 0.41,
  ay: -0.1,
  arx: 1900,
  ary: 1830,
  aAlpha: 0.225,
  aStop: 0.43,

  /** Second orb (warm color, pressing in from bottom-right) */
  bx: 1.08,
  by: 0.68,
  brx: 2400,
  bry: 1100,
  bAlpha: 0.025,
  bStop: 0.13,

  /** Dither: noise intensity to break up color banding (0.004 ≈ 1/255). Increasing grainSize turns dither into visible grain */
  grain: 0.008,
  grainSize: 2,

  /**
   * Color. Left empty, it follows the skin (base color `--ui-bg`, light `--ui-accent`); if filled,
   * uses the specified value.
   *
   * Base color and the cool orb are left empty: when switching skins or changing accent color in
   * settings, this layer follows. The warm orb is the orange chosen by the user (user decision, 2026-10-23)
   * and has nothing to do with skin, so it is hardcoded: the same pattern as `BrandCanvas.tsx`
   * where "cool side follows skin, warm side is hardcoded".
   */
  bg: "",
  colA: "",
  colB: "#FF7B00",

  /** Internal resolution = min(device pixel ratio, 2) × this number. Gradients are cheap; 1 gives 1:1 */
  resScale: 1,
};

const VERT = `#version 300 es
void main(){ vec2 p = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2); gl_Position = vec4(p*2.0-1.0,0.0,1.0); }`;

const FRAG = `#version 300 es
precision highp float;
out vec4 fragColor;

uniform vec2 uRes;      // 画布的内部像素
uniform float uPxScale; // 内部像素 / CSS 像素
/* 循环相位，0→1 走满一圈回到起点 */
uniform float uLoop;

uniform vec3 uBg;
uniform vec3 uColA;
uniform vec3 uColB;

uniform float uAx, uAy, uArx, uAry, uAAlpha, uAStop;
uniform float uBx, uBy, uBrx, uBry, uBAlpha, uBStop;
uniform float uGrain, uGrainSize, uDrift;
uniform float uRefW, uRefH;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

/*
 * 一团 CSS 式的径向光：radial-gradient(rx ry at cx cy, 色 浓度 a0, transparent stop)。
 * CSS 的渐变是在**预乘**的空间里线性插值的，所以色相一路不变，只有 alpha 从 a0 直线降到 0，
 * 到 stop（相对椭圆半径的比例）就没了。这里照这个算，不用 smoothstep，不然和官网对不上。
 */
float glow(vec2 px, vec2 c, vec2 r, float stop, float a0) {
  float t = length((px - c) / max(r, vec2(1.0)));
  return a0 * clamp(1.0 - t / max(stop, 1e-4), 0.0, 1.0);
}

void main() {
  float s = max(uPxScale, 1e-4);
  vec2 cssPx = gl_FragCoord.xy / s;
  float wCss = uRes.x / s;
  float hCss = uRes.y / s;
  // gl_FragCoord 的 y 从下往上数，CSS 从上往下：翻过来，位置参数才和官网写的那组数一个意思
  cssPx.y = hCss - cssPx.y;

  // 两团朝相反方向飘，错开一点才看得出是两团；drift = 0 时这一项是 0
  /*
   * 两团朝相反方向飘，错开一点才看得出是两团；drift = 0 时这一项是 0。
   *
   * 两个频率取 4 和 3（原来是 1 和 0.75，比值一样是 0.75，但不是整数倍频）：
   * 整数倍频才保证 uLoop 走满一圈时两项同时回到出发点 —— 预渲染成视频要靠这一条接上循环。
   * 快慢没变：一圈的秒数由 LOOK.loopSeconds 定。
   */
  vec2 d = uDrift * vec2(sin(uLoop * 6.2831853 * 4.0), cos(uLoop * 6.2831853 * 3.0));

  /*
   * 以屏幕中心对齐：位置不按当前视口的比例算，而是换算成相对中心的固定像素偏移
   * （基准视口见组件里的 refW / refH）。视口正好是基准尺寸时结果和「位置 × 视口」相同；
   * 屏幕小了就是同一张构图的中心裁切。
   */
  vec2 mid = vec2(wCss, hCss) * 0.5;
  vec2 ref = vec2(max(uRefW, 1.0), max(uRefH, 1.0));

  float aA = glow(cssPx, mid + (vec2(uAx, uAy) - 0.5) * ref + d, vec2(uArx, uAry), uAStop, uAAlpha);
  float aB = glow(cssPx, mid + (vec2(uBx, uBy) - 0.5) * ref - d, vec2(uBrx, uBry), uBStop, uBAlpha);

  // 叠的顺序同官网：CSS 里先写的那层在上面，所以 B 先压在底色上，A 再压上去
  vec3 col = uBg;
  col = mix(col, uColB, aB);
  col = mix(col, uColA, aA);

  // 抖动：深色上的大面积渐变在 8 位里会起一圈圈色带，撒一点噪声把台阶打散
  float n = hash(floor(gl_FragCoord.xy / max(uGrainSize, 1.0)) + 0.5);
  col += (n - 0.5) * uGrain;

  fragColor = vec4(max(col, 0.0), 1.0);
}`;

function hexToRgb(hex: string, fallback: [number, number, number]): [number, number, number] {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return fallback;
  const n = parseInt(m[1], 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function BrandGlow({ params, t = 0, stage }: CardProps<Params>) {
  const ref = useRef<HTMLCanvasElement>(null);
  // Aspect ratio follows the project (the two orb radii are fixed pixels, so composition matches
  // whatever size it renders at)
  const w = Math.max(2, Math.round(stage?.width ?? WIDTH));
  const h = Math.max(2, Math.round(stage?.height ?? HEIGHT));
  useLayoutEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const gl = canvas.getContext("webgl2", { alpha: true, premultipliedAlpha: true, antialias: false, preserveDrawingBuffer: true });
    // If WebGL2 fails to start, draw a solid base color so the whole card does not crash
    if (!gl) {
      const c2 = canvas.getContext("2d");
      if (c2) { c2.fillStyle = params.bg || "#111016"; c2.fillRect(0, 0, w, h); }
      return;
    }
    const make = (type: number, src: string) => {
      const sh = gl.createShader(type)!;
      gl.shaderSource(sh, src); gl.compileShader(sh);
      if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(sh) ?? "shader");
      return sh;
    };
    const prog = gl.createProgram()!;
    gl.attachShader(prog, make(gl.VERTEX_SHADER, VERT));
    gl.attachShader(prog, make(gl.FRAGMENT_SHADER, FRAG));
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(prog) ?? "link");
    gl.useProgram(prog);
    const at = (n: string) => gl.getUniformLocation(prog, n);

    gl.uniform1f(at("uAx"), LOOK.ax);
    gl.uniform1f(at("uAy"), LOOK.ay);
    gl.uniform1f(at("uArx"), LOOK.arx);
    gl.uniform1f(at("uAry"), LOOK.ary);
    gl.uniform1f(at("uAAlpha"), LOOK.aAlpha);
    gl.uniform1f(at("uAStop"), LOOK.aStop);
    gl.uniform1f(at("uBx"), LOOK.bx);
    gl.uniform1f(at("uBy"), LOOK.by);
    gl.uniform1f(at("uBrx"), LOOK.brx);
    gl.uniform1f(at("uBry"), LOOK.bry);
    gl.uniform1f(at("uBAlpha"), LOOK.bAlpha);
    gl.uniform1f(at("uBStop"), LOOK.bStop);
    gl.uniform1f(at("uGrain"), LOOK.grain);
    gl.uniform1f(at("uGrainSize"), LOOK.grainSize);
    gl.uniform1f(at("uDrift"), LOOK.drift);
    gl.uniform1f(at("uRefW"), LOOK.refW);
    gl.uniform1f(at("uRefH"), LOOK.refH);
    gl.uniform3f(at("uBg"), ...hexToRgb(params.bg, [0.067, 0.063, 0.086]));
    gl.uniform3f(at("uColA"), ...hexToRgb(params.colA, [0.000, 0.859, 0.859]));
    gl.uniform3f(at("uColB"), ...hexToRgb(params.colB, [1.000, 0.482, 0.000]));
    gl.uniform2f(at("uRes"), w, h);
    gl.uniform1f(at("uPxScale"), 1);
    // Completing a full cycle returns to the start: the frame where t reaches loopSeconds evaluates
    // identically to t = 0
    const secs = Math.max(0.001, params.loopSeconds);
    gl.uniform1f(at("uLoop"), ((t % secs) + secs) % secs / secs);

    gl.viewport(0, 0, w, h);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.deleteProgram(prog);
  }, [t, params.bg, params.colA, params.colB, params.loopSeconds, w, h]);
  return <canvas ref={ref} width={w} height={h} style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }} />;
}

export const brandGlow: CardDef<Params> = {
  id: "pc-brand-glow",
  name: "Home page background glow",
  description: "The two background glows on the website home page and the mobile app login. The picture is a function of the frame clock and loops back to the start after a full cycle, made specifically to be prerendered into a seamless looping video.",
  source: "user",
  useWhen: "Only for rendering the home page / mobile login background glow into a looping video; for a background glow elsewhere, write another card.",
  tags: ["background", "glow", "shader", "home page"],
  frameMode: "direct",
  defaults: { bg: "#111016", colA: "#00dbdb", colB: "#FF7B00", loopSeconds: 28 },
  controls: [
    { key: "bg", label: "Base color", type: "color" },
    { key: "colA", label: "Cool glow", type: "color" },
    { key: "colB", label: "Warm glow", type: "color" },
    { key: "loopSeconds", label: "Loop seconds", type: "number", min: 4, max: 600, step: 1 },
  ],
  Component: BrandGlow,
};
